const input = $input.first().json;

const result = input.structuredContent?.results?.[0];

if (!result || !Array.isArray(result.rows)) {
  throw new Error('No keyword rows found in OpenSEO response');
}

const seedTopic = result.seed || '';

return result.rows.map(row => ({
  json: {
    seed_topic: seedTopic,
    keyword: row.keyword,
    search_volume: row.searchVolume ?? null,
    keyword_difficulty: row.keywordDifficulty ?? null,
    cpc: row.cpc ?? null,
    competition: row.competition ?? null,
    intent: row.intent ?? null
  }
}));

const raw = $input.first().json.choices?.[0]?.message?.content;

if (!raw) {
  throw new Error('No AI analysis found');
}

let cleaned = raw.trim();

// Remove markdown fences if the model ever adds them
cleaned = cleaned
  .replace(/^```json\s*/i, '')
  .replace(/^```\s*/i, '')
  .replace(/```$/i, '')
  .trim();

let parsed;

try {
  parsed = JSON.parse(cleaned);
} catch (error) {
  throw new Error(`Could not parse AI analysis JSON: ${error.message}`);
}

return [{
  json: parsed
}];

const data = $input.first().json;

const opportunities = data.article_opportunities || [];

if (opportunities.length === 0) {
  throw new Error('No article opportunities found');
}

return opportunities.map(article => ({
  json: {
    seed_topic: data.seed_topic,

    topic: article.topic,

    primary_keyword: article.primary_keyword?.keyword || "",
    search_volume: article.primary_keyword?.search_volume ?? null,
    keyword_difficulty: article.primary_keyword?.keyword_difficulty ?? null,
    cpc: article.primary_keyword?.cpc ?? null,
    competition: article.primary_keyword?.competition ?? null,

    secondary_keywords: article.secondary_keywords || [],

    search_intent: article.search_intent?.primary || "",
    secondary_intent: article.search_intent?.secondary || [],

    content_objective: article.content_objective || "",
    questions_to_cover: article.questions_to_cover || [],

    product_relevance: article.product_relevance || "",
    audience_fit: article.audience_fit || "",
    seo_rationale: article.seo_rationale || "",
    article_angle: article.article_angle || ""
  }
}));

const items = $input.all();

// Remove exact duplicates, while keeping all potentially
// interesting keywords — even if they aren't article opportunities.
const seen = new Set();

const cleaned = items
  .map(item => item.json)
  .filter(row => {
    const keyword = (row.keyword || '').trim().toLowerCase();

    if (!keyword || seen.has(keyword)) {
      return false;
    }

    seen.add(keyword);
    return true;
  })
  .map(row => {
  const observedDate = new Date().toISOString().split('T')[0];

  return {
    seed_topic: row.seed_topic,
    keyword: row.keyword,
    search_volume: row.search_volume ?? null,
    keyword_difficulty: row.keyword_difficulty ?? null,
    intent: row.intent ?? null,
    cpc: row.cpc ?? null,
    competition: row.competition ?? null,
    observed_date: observedDate,
    observation_key: `${row.seed_topic}|${row.keyword}|${observedDate}`
  };
});

// Highest search volume first.
// Keywords without volume go to the bottom.
cleaned.sort((a, b) => {
  const volumeA = a.search_volume ?? -1;
  const volumeB = b.search_volume ?? -1;

  return volumeB - volumeA;
});

return cleaned.map(row => ({
  json: row
}));

const rows = $input.all().map(item => item.json).filter(row => row.keyword);
if (rows.length === 0) throw new Error('No search-demand keywords to save');
const seed = rows[0].seed_topic || 'SEO discovery';
const observed = rows[0].observed_date || new Date().toISOString().slice(0, 10);
const top = rows.slice(0, 30);
const lines = top.map((row, index) => {
  const volume = row.search_volume ?? 'unknown';
  const difficulty = row.keyword_difficulty ?? 'unknown';
  const intent = row.intent || 'unclassified';
  const phrase = String(row.keyword).trim();
  const format = /how to|guide|tutorial/i.test(phrase) ? 'short how-to or checklist'
    : /vs|versus|compare|alternative/i.test(phrase) ? 'comparison carousel'
    : /what is|meaning|definition/i.test(phrase) ? 'plain-language explainer'
    : 'question-led explainer';
  return `${index + 1}. ${phrase}\n   Social idea starter: ${format} on this search question.\n   Search volume: ${volume}; difficulty: ${difficulty}; intent: ${intent}.`;
});
const content = [
  `# ACF social media idea prompts: ${seed}`,
  `Observed: ${observed}. Source: OpenSEO keyword research. ${rows.length} distinct keyword(s); top ${top.length} by search volume shown.`,
  'These are prompts for editorial review, not verified facts or ready-to-publish posts. Check the keyword meaning, evidence, brand fit, and AI Context Flow relevance before using any idea.',
  ...lines,
].join('\n\n');
return [{ json: { plurality_social_ideas: {
  profile_id: 'REPLACE_WITH_YOUR_SOCIAL_IDEAS_BUCKET_ID',
  title: `ACF social ideas | ${seed} | ${observed}`,
  content,
  source_platform: 'n8n',
}, idea_count: top.length, total_keywords: rows.length } }];
